"""Generate one self-contained, offline reviewer interface from a completed run."""
from __future__ import annotations

import json
from pathlib import Path


def render_workbench(report: dict, output_path: Path) -> None:
    """Embed finite JSON as data, escaping HTML script terminators and Unicode separators."""
    if not isinstance(report, dict) or not isinstance(report.get("meta"), dict):
        raise ValueError("report must contain a meta object")
    payload = json.dumps(report, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    for literal, escaped in (("&", "\\u0026"), ("<", "\\u003c"), (">", "\\u003e"),
                             ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        payload = payload.replace(literal, escaped)
    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(_TEMPLATE.replace("__REPORT_JSON__", payload), encoding="utf-8")


